const BOTS=[{loc:'htgHvVfBZ1WH3UpQoxaa',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'PXyGarBjp2lwuVBdA81P',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'1lP8kn6tPERda0fT4zVT',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'XAF0RGBybE8RoesJhSiz',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'96LqPx5WmcloFPZZe1hy',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'kuO6oj3iKtz5PQUu4WZ0',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'NsDKFz05b8v0P86nTc2o',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'sEjuiURUKweddSIqjcjT',tok:'pit-REDACTED_PER_LOCATION_TOKEN'},{loc:'qT3OTNWfVeq0tNWklhMK',tok:'pit-REDACTED_PER_LOCATION_TOKEN'}];
const START=Date.parse('2026-01-01T00:00:00Z');
const out=[];
for(const b of BOTS){
  const seen={}; const detail=[]; let after=null; let pages=0; let done=false;
  while(!done && pages<800){
    let url='https://services.leadconnectorhq.com/conversations/search?locationId='+b.loc+'&limit=100&sortBy=last_message_date&sort=desc';
    if(after) url+='&startAfterDate='+after;
    let resp;
    try{resp=await this.helpers.httpRequest({method:'GET',url,headers:{Authorization:'Bearer '+b.tok,Version:'2021-04-15'},json:true});}catch(e){break;}
    const convs=(resp&&resp.conversations)||[];
    if(!convs.length) break;
    let oldest=null;
    for(const c of convs){
      const ts=Number(c.lastMessageDate||c.dateUpdated||0);
      if(oldest===null||ts<oldest) oldest=ts;
      if(ts && ts<START){ done=true; continue; }
      if(!c.contactId||seen[c.contactId]) continue; seen[c.contactId]=1;
      const d=new Date(ts); const ym=d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0');
      const body=(c.lastMessageBody||'').trim();
      detail.push({contact_id:c.contactId,payout_month:ym,contact_name:(c.fullName||c.contactName||''),email:c.email||null,sentiment:'Unclassified',last_message:body?body.slice(0,1500):null,sf_lead_id:null,sf_stage:null,funded_commission:0,ts:ts});
    }
    if(oldest===null||oldest<START){ done=true; }
    after=oldest; pages++;
  }
  out.push({json:{p_location:b.loc,p_detail:detail,count:detail.length}});
}
return out;
